import React, { useEffect, useState } from 'react';

type Comment = {
  id: number;
  author: any;
  body: string;
  avatar: string;
};

export function CommentList(props: any) {
  const [list, setList] = useState([] as any);
  const [keyword, setKeyword] = useState('');

  useEffect(() => {
    fetch('/api/comments?topic=' + props.topic)
      .then((r) => r.json())
      .then((d) => {
        setList(d.data);
      });
  }, [props.topic]);

  const onSearch = (e: any) => {
    setKeyword(e.target.value);
    window.location.href = '/search?q=' + e.target.value;
  };

  const highlight = (text, kw) => {
    if (!kw) return text;
    return text.replace(new RegExp(kw, 'g'), '<mark>' + kw + '</mark>');
  };

  return (
    <div>
      <input type="text" onChange={onSearch} />
      <div id="tip" dangerouslySetInnerHTML={{ __html: props.tip }} />
      {list.map((c: Comment, i: number) => (
        <div key={i} className="comment">
          <img src={c.avatar} />
          <a href={'javascript:void(0)'} onClick={() => eval(c.author.onClick)}>
            {c.author.name}
          </a>
          <div
            className="body"
            dangerouslySetInnerHTML={{ __html: highlight(c.body, keyword) }}
          />
        </div>
      ))}
    </div>
  );
}

import React, { useEffect, useState } from 'react';

export function UserProfile({ userId }: { userId: string }) {
  const [user, setUser] = useState<any>(null);
  const [posts, setPosts] = useState<any>([]);
  const [loading, setLoading] = useState(false);
  const [err, setErr] = useState('');

  useEffect(() => {
    setLoading(true);
    fetch('/api/user/' + userId)
      .then((r) => r.json())
      .then((u) => {
        setUser(u);
        fetch('/api/posts?uid=' + u.id)
          .then((r) => r.json())
          .then((p) => {
            setPosts(p);
            setLoading(false);
          });
      })
      .catch((e) => {
        setErr(e.message);
      });
  }, [userId]);

  useEffect(() => {
    const t = setInterval(() => {
      fetch('/api/user/' + userId + '/online')
        .then((r) => r.json())
        .then((d) => setUser((prev: any) => ({ ...prev, online: d.online })));
    }, 3000);
  }, [userId]);

  const onRefresh = async () => {
    const u = await fetch('/api/user/' + userId).then((r) => r.json());
    setUser(u);
    const p = await fetch('/api/posts?uid=' + u.id).then((r) => r.json());
    setPosts(p);
  };

  return (
    <div>
      {loading && <div>loading...</div>}
      <h2>{user.name}</h2>
      <p>粉丝 {user.followers}</p>
      <button onClick={onRefresh}>刷新</button>
      <ul>
        {posts.map((p: any) => (
          <li key={p.id}>{p.title}</li>
        ))}
      </ul>
    </div>
  );
}

import React, { useState } from 'react';

export function SignupForm() {
  const [email, setEmail] = useState('');
  const [pwd, setPwd] = useState('');
  const [age, setAge] = useState('');
  const [err, setErr] = useState('');

  const submit = () => {
    if (email == '' || pwd == '') {
      setErr('请填写');
      return;
    }
    if (Number(age) < 18) {
      setErr('年龄不够');
      return;
    }
    fetch('/api/signup', {
      method: 'POST',
      body: JSON.stringify({ email, pwd, age }),
    });
  };

  return (
    <div className="signup">
      <div className="title" onClick={() => window.history.back()}>
        ← 返回
      </div>
      <h3>注册</h3>
      <div className="row">
        <div>邮箱</div>
        <input
          type="text"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
        />
      </div>
      <div className="row">
        <div>密码</div>
        <input value={pwd} onChange={(e) => setPwd(e.target.value)} />
      </div>
      <div className="row">
        <div>年龄</div>
        <input
          value={age}
          onChange={(e) => setAge(e.target.value)}
        />
      </div>
      {err && <div style={{ color: 'red' }}>{err}</div>}
      <div className="btn" onClick={submit}>
        提交
      </div>
      <img src="/decorate.png" />
      <div
        className="close"
        onClick={() => (document.getElementById('modal')!.style.display = 'none')}
      >
        x
      </div>
    </div>
  );
}
